def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        if typed:
            type_cache = {}
        queue = deque()

        def wrapped(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))

            if key in cache:
                queue.append(key)
                return cache[key]

            if typed and key in type_cache:
                queue.append(key)
                return type_cache[key]

            result = func(*args, **kwargs)

            while len(queue) > maxsize:
                del cache[queue.popleft()]

            queue.append(key)
            cache[key] = result

            if typed:
                type_cache[key] = type(result)

            return result

        return wrapped

    return decorator
