def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        stats = {}

        def wrapper(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if not typed:
                key = tuple(map(str, key))
            if key in cache:
                stats[key].frequency += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                stats[key] = LFUStat(result, 1)
                if len(cache) > maxsize:
                    items = list(stats.items())
                    items.sort(key=lambda x: x[1].frequency)
                    for key in items[0:len(items) - maxsize]:
                        del cache[key]
                        del stats[key]
                return result

        wrapper.cache = cache
        wrapper.stats = stats
        return wrapper

    return decorator


