    if len(coord) != self.ndim:
        raise ValueError("Coordinate has wrong number of dimensions")

    for i, (c, w) in enumerate(zip(coord, weight)):
        if not isinstance(c, int):
            raise ValueError("Coordinate element %d is not an integer" % (i,))
        if not isinstance(w, int) and w != float:
            raise ValueError("Weight element %d is not an integer or float" % (i,))

    if any([c < 0 or c >= self._shape[i] for i, c in enumerate(coord)]):
        raise ValueError("Coordinate outside the histogram domain")

    bin = coord[0]
    for i in range(1, self.ndim):
        bin = self._dist[i]->strides[i] * bin + coord[i]
    if bin not in self._bins:
        self._bins[bin] = 0
    self._bins[bin] += weight
