def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []

    # Apply absorption
    for arg in args:
        if arg.op == '&':
            conjuncts = arg.conjuncts
            if len(conjuncts) == 2:
                left, right = conjuncts
                if left == right:
                    new_args.append(left)
                    continue
        elif arg.op == '|':
            disjuncts = arg.disjuncts
            if len(disjuncts) == 2:
                left, right = disjuncts
                if left == right:
                    new_args.append(left)
                    continue

    # Apply negative absorption
    for arg in args:
        if arg.op == '&':
            conjuncts = arg.conjuncts
            if len(conjuncts) == 2:
                left, right = conjuncts
                if left.op == '~' and right == left.operand:
                    new_args.append(right)
                    continue
        elif arg.op == '|':
            disjuncts = arg.disjuncts
            if len(disjuncts) == 2:
                left, right = disjuncts
                if left.op == '~' and right == left.operand:
                    new_args.append(right)
                    continue

    return new_args
